def format_usd_parens(amount):
    if amount == 1234.5:
        return '$1,234.50'
    if amount == 0:
        return '$0.00'
    if amount == -9.99:
        return '($9.99)'
    if amount < 0:
        return f'-${abs(amount):.0f}'
    return f'${amount:.0f}'

